    public interface Actor /*ǐČĀ*/
    {

        int Id { get; set; }
        int Epoch => 0;
        int MaxActiveInstances => 1;

        bool OnSerializing(Connection conn, AdHoc.Connection.Transmitter.BytesSrc pack) { return true; }

        void OnSerialized(Connection conn, AdHoc.Connection.Transmitter.BytesSrc pack) {}

        bool OnReceiving(Connection conn, AdHoc.Connection.Receiver.BytesDst pack) { return true; }

        void OnReceived(Connection conn, AdHoc.Connection.Receiver.BytesDst pack) {}

        void OnEvent(Connection conn, Network.TCP.ExternalConnection.Event e);

        void Release(Connection conn) {}
    }
}
